var maxCoins = function(nums) {
    const values = [1];
    for (const value of nums) {
        if (value > 0) values.push(value);
    }
    values.push(1);
    const size = values.length;
    const dp = Array.from({ length: size }, () => new Array(size).fill(0));

    for (let gap = 2; gap < size; gap++) {
        for (let left = 0; left < size - gap; left++) {
            const right = left + gap;
            let best = 0;
            for (let last = left + 1; last < right; last++) {
                const gain = values[left] * values[last] * values[right]
                    + dp[left][last] + dp[last][right];
                if (gain > best) best = gain;
            }
            dp[left][right] = best;
        }
    }

    return dp[0][size - 1];
};

solution.python:
from typing import List

class Solution:
    def maxCoins(self, nums: List[int]) -> int:
        values = [1] + [value for value in nums if value > 0] + [1]
        size = len(values)
        dp = [[0] * size for _ in range(size)]

        for gap in range(2, size):
            for left in range(size - gap):
                right = left + gap
                dp[left][right] = max(
                    values[left] * values[last] * values[right]
                    + dp[left][last] + dp[last][right]
                    for last in range(left + 1, right)
                )

        return dp[0][size - 1]
